// Hyperjump — the run arc (slice H1; design: Hyperjump APPROVED 2026-10-04).
//
// A run is FOUR SECTORS of five jumps. Jumps 5 / 10 / 15 / 20 are Black Hole
// bosses; clearing jump 20 reaches the Core and WINS. Between sectors a banner
// announces the next one. The run in progress is saved on the device after every
// step, so leaving (or the app being closed) never loses it.

export const JUMPS_PER_SECTOR = 5;
export const FINAL_JUMP = 20;

export const SECTORS = [
  { id: 'inner', name: 'Inner Orbit', power: 0, blurb: 'White dice, any maths. Four warm-up jumps, then a Black Hole.' }, // jump 5 is a boss, not a warm-up
  { id: 'belt', name: 'Asteroid Belt', power: 1, blurb: 'The coloured power dice arrive — use 1 of the 3 correctly (all 3 is a Perfect) — and a gold Tens Die (10–60) joins for the big targets.' },
  { id: 'deep', name: 'Deep Space', power: 2, blurb: 'Use 2 of the 3 power dice correctly.' },
  { id: 'core', name: 'The Core', power: 3, blurb: 'Perfect only: all 3 power dice, every jump. Clear jump 20 to win.' },
];

/**
 * Where Practice can start (David, 2026-10-22): the first jump of any sector the player has reached.
 * best = the most jumps cleared in one run (bests.js); sector n opens once a run has cleared 5 × (n − 1).
 * @returns {Array<{ number: number, id: string, name: string, power: number, jump: number, open: boolean }>}
 */
export function practiceStarts(best = 0) {
  return SECTORS.map((s, k) => ({ number: k + 1, id: s.id, name: s.name, power: s.power, jump: k * JUMPS_PER_SECTOR + 1, open: k === 0 || best >= k * JUMPS_PER_SECTOR }));
}

/** Sector (1-based number + rules) for a jump. Jumps past 20 stay in the Core. */
export function sectorFor(jump) {
  const n = Math.min(SECTORS.length, Math.ceil(jump / JUMPS_PER_SECTOR));
  return { number: n, ...SECTORS[n - 1] };
}

/**
 * What comes after clearing a jump (once the artifact draft is done):
 * 'won' at the Core, a 'sector' banner when a new sector begins, otherwise the next 'jump'.
 */
export function afterClear(jump) {
  if (jump >= FINAL_JUMP) return 'won';
  if (jump % JUMPS_PER_SECTOR === 0) return 'sector';
  return 'jump';
}

/** How many jumps a saved run has cleared. On the draft screen the jump just cleared is still `jump`. */
export const clearedOf = (run) => (run.phase === 'draft' ? run.jump : run.jump - 1);

/** Is this a Daily seed ("hyperjump-YYYY-MM-DD")? Free seeds are `hyperjump-<random number>`. */
export const isDailySeed = (seed) => /^hyperjump-\d{4}-\d{2}-\d{2}$/.test(seed ?? '');

/** Does clearing this jump end the run in victory (no artifact draft first)? */
export const isWinningJump = (jump) => jump >= FINAL_JUMP;

// ── Save / resume (device-local) ────────────────────────────────────────────────

export const RUN_KEY = 'sector73.hyperjump.run';
const VERSION = 1;
const RESUMABLE = new Set(['jump', 'draft', 'sector']);

/**
 * Save the run in progress.
 * @param {{ seed: string, phase: string, jump: number, rollK: number, oxygen: number, fuel: number,
 *   jumpSeconds?: number, artifacts: string[], slots: number, lightYears: number, overrides?: object, colorOverrides?: object, used?: object, lastClear?: object|null,
 *   fuelCellPaid?: boolean, runLog?: Array<{ jump: number, perfect?: boolean, rerolled?: boolean }>, deflectedJump?: number|null,
 *   perfectStreak?: number, runSeconds?: number, helped?: boolean, scansUsed?: number, rerollsUsed?: number, startJump?: number }} run  (older saves may also carry reserve/salvage/charges: ignored since 2026-10-22)
 */
export function saveRun(run, storage = globalThis.localStorage) {
  try {
    if (!RESUMABLE.has(run.phase)) { storage?.removeItem(RUN_KEY); return; }
    storage?.setItem(RUN_KEY, JSON.stringify({ v: VERSION, ...run }));
  } catch {
    // Storage blocked or full: the run still plays, it just can't resume.
  }
}

/** The saved run, or null (none, unreadable, or from an older save format). */
export function loadRun(storage = globalThis.localStorage) {
  try {
    const raw = storage?.getItem(RUN_KEY);
    if (!raw) return null;
    const run = JSON.parse(raw);
    if (run?.v !== VERSION || typeof run.seed !== 'string' || !RESUMABLE.has(run.phase)) return null;
    if (!Number.isInteger(run.jump) || run.jump < 1 || run.jump > FINAL_JUMP) return null;
    return run;
  } catch {
    return null;
  }
}

export function clearRun(storage = globalThis.localStorage) {
  try { storage?.removeItem(RUN_KEY); } catch { /* nothing saved */ }
}

// ── One Daily attempt (David, 2026-10-14; contrarian review: after a death the Daily could be
// restarted with every board already known). DAILY RUN marks it; it can be RESUMED while saved,
// but once it ends — or is abandoned for another run — the day's Daily is spent.
export const DAILY_KEY = 'sector73.hyperjump.daily';

/** Today's attempt: { date, status: 'started'|'over'|'won'|'elsewhere', jump, lightYears?, card? } or null. */
export function readDailyAttempt(date, storage = globalThis.localStorage) {
  try {
    const s = JSON.parse(storage?.getItem(DAILY_KEY) ?? 'null');
    return s && s.date === date ? s : null;
  } catch {
    return null;
  }
}

/**
 * @param {object} [extra] kept with the attempt for the "done" card: { lightYears, card } (card = the share text)
 */
export function markDailyAttempt(date, status, jump = 0, storage = globalThis.localStorage, extra = {}) {
  const s = { date, status, jump, ...extra };
  try { storage?.setItem(DAILY_KEY, JSON.stringify(s)); } catch { /* storage blocked */ }
  return s;
}
