// The Scanner's search, off the main thread (2026-10-22: the old in-page search froze the jump screen
// for up to 2.6 s). The jump screen posts each new board here as soon as the dice land, so pressing
// Scan answers at once. One message in, one out: { id, params } → { id, result }.

import { findRoute } from './scanner';

self.onmessage = (e) => {
  const { id, params } = e.data || {};
  let result;
  try { result = findRoute(params); } catch { result = { status: 'unknown' }; }
  self.postMessage({ id, result });
};
