// Hyperjump's Scanner. David, 2026-10-22: the Scan shows the SHAPE of a real route with every number
// blanked, e.g. "(□ × □ × □) − □ + □": which operators, and how they group. Never a digit, never
// which die goes where, so the puzzle stays yours. A second Scan lights up the part of that route
// that carries most of the target. (Before: "Try 6 ^ 4 = 1296", one dice-on-dice step from the
// FIRST route found; it was part of a median 1–9% of the real solutions. Research 2026-10-22.)
//
// The search is the "24 game": take two numbers, combine them with an operator, repeat until one
// number is left. It runs on a NODE budget (not a clock), so it can never hang and tests are
// deterministic. Every route is re-checked with judgeJump, the game's own judge, so a shape is
// always the shape of an answer the JUMP button accepts.
//
//   scan()       the fast search: stops at the first route (also the solver other tests use).
//   findRoute()  keeps searching and keeps the route a person would write: few brackets, no needless
//                ^ or ÷, no giant middle numbers, power dice next to their own keys.
//   routeShape() the blanked shape of a route, with its biggest part marked.
// The jump screen runs findRoute in a Web Worker as soon as the dice land (./scanWorker.js).

import { judgeJump, powerNeeded, targetFor } from './logic';

const FITS = { green: ['+', '-'], blue: ['*', '/'], red: ['^'] };
const fits = (color, op) => Boolean(FITS[color]?.includes(op));
const PREC = { '+': 1, '-': 1, '*': 2, '/': 2, '^': 3 };
export const SHAPE_GLYPH = Object.freeze({ '+': '+', '-': '−', '*': '×', '/': '÷', '^': '^' });
export const BLANK = '□';

/** The in-game budgets: the first pass proves a route exists, the second keeps the simplest one. */
// The first pass runs in the background as soon as the dice land, so it can afford a big budget: at
// 600k nodes some hard boss rolls (× burned at jump 15) ran out (proto/curse-reach.mjs, 2026-10-22).
export const FAST_NODES = 1500000;
export const SIMPLE_NODES = 150000;

const combine = (x, y, op) => {
  if (op === '+') return x + y;
  if (op === '-') return x - y;
  if (op === '*') return x * y;
  if (op === '/') return y !== 0 && x % y === 0 ? x / y : NaN;
  return y >= 0 && y <= 6 && Math.abs(x) <= 60 ? x ** y : NaN; // ^, kept small
};

/**
 * Tokens for a route tree, with only the brackets it needs (× before +, ^ binds tightest, a right
 * operand of the same strength keeps its brackets: 8 − (3 + 2)).
 * @returns {Array<any>} tokens: { t: 'die', i } or { t: 'op', v }
 */
export function treeTokens(n, parentOp = null, right = false) {
  if (n.die != null) return [{ t: 'die', i: n.die }];
  const inner = [...treeTokens(n.l, n.op, false), { t: 'op', v: n.op }, ...treeTokens(n.r, n.op, true)];
  const needs = parentOp != null && (PREC[n.op] < PREC[parentOp]
    || (PREC[n.op] === PREC[parentOp] && (right || n.op === '^' || parentOp === '^')));
  return needs ? [{ t: 'op', v: '(' }, ...inner, { t: 'op', v: ')' }] : inner;
}

/**
 * The shared search. `onRoute(tree, tokens, cost)` is called for every route the judge accepts and
 * returns true to stop. Returns { nodes, exhausted } — exhausted = the whole search space was
 * walked, so "no route" is the truth (within the Scanner's maths: whole numbers 0–5000, ^ up to 6).
 */
function search(p, onRoute) {
  const { values, colors, jump, curse = null, artifacts = [], burnedOp = null, target = null, maxNodes } = p;
  const T = target ?? targetFor(jump);
  const ops = ['+', '-', '*', '/', '^'].filter((o) => !(curse === 'eventHorizon' && o === '+') && o !== burnedOp);
  const need = powerNeeded(jump, curse);
  const isPower = (i) => Boolean(FITS[colors[i]]);
  const seen = new Set();
  let nodes = 0;
  let stop = false;
  let cut = false;

  const dfs = (items) => {
    if (stop) return;
    if (++nodes > maxNodes) { cut = true; stop = true; return; }
    if (items.length === 1) {
      const it = items[0];
      const tokens = treeTokens(it.node);
      if (!judgeJump({ tokens, values, colors, jump, artifacts, curse, burnedOp, target: T }).ok) return;
      const cost = it.cost + 2 * tokens.filter((t) => t.t === 'op' && t.v === '(').length;
      if (onRoute(it.node, tokens, cost)) stop = true;
      return;
    }
    // Same multiset of pieces (value + die colour, or value + power used) = same future.
    const key = items.map((x) => `${x.v}${x.node.die != null ? `d${colors[x.node.die]}` : `p${x.pw}`}`).sort().join(',');
    if (seen.has(key)) return;
    seen.add(key);
    // Prune: power used so far + power dice still unplaced can no longer reach the rule.
    if (items.reduce((s, x) => s + (x.node.die != null ? (isPower(x.node.die) ? 1 : 0) : x.pw), 0) < need) return;
    // Moves that give a power die its own operator go first: that is where the rule is won.
    const moves = [];
    for (let a = 0; a < items.length; a++) {
      for (let b = 0; b < items.length; b++) {
        if (a === b) continue;
        for (const op of ops) {
          if ((op === '+' || op === '*') && a > b) continue; // commutative: one order is enough
          const x = items[a].node; const y = items[b].node;
          const gain = (x.die != null && fits(colors[x.die], op) ? 1 : 0) + (y.die != null && fits(colors[y.die], op) ? 1 : 0);
          moves.push({ a, b, op, gain });
        }
      }
    }
    moves.sort((m, n) => n.gain - m.gain);
    for (const { a, b, op, gain } of moves) {
      const x = items[a]; const y = items[b];
      const v = combine(x.v, y.v, op);
      if (!Number.isFinite(v) || v < 0 || v > 5000) continue;
      // Cost = how odd it reads: ^ and ÷ are harder, a middle number far past the target is strange,
      // and a power die under a key that does not count for it reads like wrong advice.
      const wrong = [x, y].filter((z) => z.node.die != null && isPower(z.node.die) && !fits(colors[z.node.die], op)).length;
      const cost = x.cost + y.cost + (op === '^' ? 3 : op === '/' ? 1 : 0) + (v > 2 * T ? 4 : 0) + 2 * wrong;
      dfs([...items.filter((_, k) => k !== a && k !== b), { v, pw: x.pw + y.pw + gain, cost, node: { op, l: x.node, r: y.node, v } }]);
      if (stop) return;
    }
  };

  // Big dice first: the backbone of a big target is usually there.
  const order = values.map((_, i) => i).sort((p2, q) => values[q] - values[p2]);
  dfs(order.map((i) => ({ v: values[i], pw: 0, cost: 0, node: { die: i, v: values[i] } })));
  return { nodes, exhausted: !cut };
}

/**
 * The fast search: the first route the judge accepts, or null.
 * @param {{ values: number[], colors: string[], jump: number, curse?: string|null, artifacts?: string[], burnedOp?: string|null, target?: number|null, maxNodes?: number }} p
 * @returns {{ tokens: Array, tree: object } | null}
 */
export function scan(p) {
  let found = null;
  search({ maxNodes: 60000, ...p }, (tree, tokens) => { found = { tokens, tree }; return true; });
  return found;
}

/**
 * The route a person would most likely write. First a fast pass proves a route exists (or that
 * none does); then a second pass keeps the cheapest route it sees.
 * @returns {{ status: 'found', tokens: Array, tree: object } | { status: 'none' } | { status: 'unknown' }}
 *   none = the search was complete and found nothing; unknown = it ran out of budget.
 */
export function findRoute(p, { fastNodes = FAST_NODES, simpleNodes = SIMPLE_NODES } = {}) {
  let first = null;
  const fast = search({ ...p, maxNodes: fastNodes }, (tree, tokens) => { first = { tokens, tree }; return true; });
  if (!first) return fast.exhausted ? { status: 'none' } : { status: 'unknown' };
  let best = null;
  search({ ...p, maxNodes: simpleNodes }, (tree, tokens, cost) => {
    if (!best || cost < best.cost) best = { tokens, tree, cost };
    return false;
  });
  const pick = best ?? first;
  return { status: 'found', tokens: pick.tokens, tree: pick.tree };
}

/**
 * The route's terms at the top: a chain of + − (or × ÷) read left to right, e.g. (A − B) + C → A, B, C.
 * The biggest term is the part that carries most of the target.
 */
function topTerms(tree) {
  if (tree.die != null) return [tree];
  const level = PREC[tree.op];
  if (level === 3) return [tree];
  const walk = (n) => (n.die == null && PREC[n.op] === level ? [...walk(n.l), n.r] : [n]);
  return walk(tree);
}

/**
 * The blanked shape of a route, as segments so the screen can light up one part.
 * `big` (level 2) marks the top-level term with the largest value; a single die is never marked,
 * because that would point at a die.
 * @param {object} tree a route tree from findRoute / scan
 * @param {{ level?: number }} [opts] level 1, or 2 to light the biggest part
 * @returns {{ text: string, segments: Array<{ text: string, big: boolean }> }}
 */
export function routeShape(tree, { level = 1 } = {}) {
  const terms = topTerms(tree);
  const candidates = terms.filter((t) => t.die == null);
  const big = level >= 2 && terms.length > 1 && candidates.length
    ? candidates.reduce((m, t) => (t.v > m.v ? t : m)) : null;
  const segments = [];
  const push = (text, isBig) => {
    const last = segments[segments.length - 1];
    if (last && last.big === isBig) last.text += text; else segments.push({ text, big: isBig });
  };
  // Re-render the tree, marking every token that belongs to the big term.
  const emit = (n, parentOp, right, inBig) => {
    const mark = inBig || n === big;
    if (n.die != null) { push(BLANK, mark); return; }
    const needs = parentOp != null && (PREC[n.op] < PREC[parentOp]
      || (PREC[n.op] === PREC[parentOp] && (right || n.op === '^' || parentOp === '^')));
    if (needs) push('(', mark);
    emit(n.l, n.op, false, mark);
    push(` ${SHAPE_GLYPH[n.op]} `, mark);
    emit(n.r, n.op, true, mark);
    if (needs) push(')', mark);
  };
  emit(tree, null, false, false);
  return { text: segments.map((s) => s.text).join(''), segments };
}

/** What the Scan line says, by level. */
export const SCAN_TEXT = Object.freeze({
  1: 'A route looks like this:',
  2: 'The lit part makes most of the target.',
  // Literal: the Scanner searches whole numbers only, so it says what IT found, not "impossible".
  none: 'Scanner finds no route with these dice. Reroll? No fuel used.',
  unknown: 'Scanner ran out of time on these dice. No fuel used.',
});
